   function somme1aN(n) {
       let total = 0;
       for (let i = 1; i <= n; i++) {
           total += i;
       }
       return total;
   }
   console.log(somme1aN(5)); // 15
   ```

9. **Algo difficile 1 — Inversion de chaîne**  
   ```javascript
   function inverserChaine(s) {
       let resultat = "";
       for (let i = s.length - 1; i >= 0; i--) {
           resultat += s[i];
       }
       return resultat;
   }
   console.log(inverserChaine("abc")); // "cba"
   ```

10. **Algo défi — Maximum d'un tableau**  
    ```javascript
    function valeurMax(tab) {
        if (tab.length === 0) return undefined;
        let max = tab[0];
        for (const num of tab) {
            if (num > max) max = num;
        }
        return max;
    }
    console.log(valeurMax([3, 7, 2])); // 7
    ```

