   ```javascript
   function puissance(base, exp) {
     if (exp < 0) throw new Error("Exponent must be non-negative");
     let resultat = 1;
     for (let i = 0; i < exp; i++) {
       resultat *= base;
     }
     return resultat;
   }
   ```

8. **Exercice algo_moyen_1 — Compter pairs**  
   ```javascript
   function compterPairs(tab) {
     let count = 0;
     for (const num of tab) {
       if (num % 2 === 0) count++;
     }
     return count;
   }
   ```

9. **Exercice algo_difficile_1 — Supprimer doublons**  
   ```javascript
   function supprimerDoublons(tab) {
     const unique = [];
     for (const item of tab) {
       if (!unique.includes(item)) {
         unique.push(item);
       }
     }
     return unique;
   }
   ```

