   function enMajuscules(chaine) {
       return chaine.toUpperCase();
   }
   console.log(enMajuscules("bonjour")); // BONJOUR
   ```

5. **Tâche 2E — Ajouter à la fin**  
   ```javascript
   function ajouterALaFin(tableau, element) {
       const nouveauTableau = [...tableau];
       nouveauTableau.push(element);
       return nouveauTableau;
   }
   console.log(ajouterALaFin([1, 2], 3)); // [1, 2, 3]
   ```

6. **Exercice algorithmique — Palindrome**  
   ```javascript
   function estPalindrome(s) {
       const chaineInverse = s.split('').reverse().join('');
       return s === chaineInverse;
   }
   console.log(estPalindrome("radar")); // true
   console.log(estPalindrome("hello")); // false
   ```

7. **Exercice algorithmique — PGCD**  
   ```javascript
   function pgcd(a, b) {
       while (b !== 0) {
           const temp = b;
           b = a % b;
           a = temp;
       }
       return a;
   }
   console.log(pgcd(12, 18)); // 6
   ```

8. **Exercice algorithmique — Nombre de mots**  
   ```javascript
   function nombreMots(s) {
       const espaces = (s.match(/\s/g) || []).length;
       return s.split(' ').filter((mot) => mot.trim() !== '').length + 1 - espaces;
   }
   console.log(nombreMots("bonjour  mon ami")); // 3
   ```

9. **Exercice algorithmique — Fusion triée**  
   ```javascript
   function fusionTriee(a, b) {
       const resultat = [];
       let i = 0;
       let j = 0;
       while (i < a.length && j < b.length) {
           if (a[i] <= b[j]) {
               resultat.push(a[i]);
               i++;
           } else {
               resultat.push(b[j]);
               j++;
           }
       }
       return [...resultat, ...a.slice(i), ...b.slice(j)];
   }
   console.log(fusionTriee([1, 3, 5], [2, 4])); // [1, 2, 3, 4, 5]
   ```

10. **Exercice algorithmique — Anagrammes**  
    ```javascript
    function sontAnagrammes(a, b) {
        const compteur = {};
        for (let char of a + b) {
            compteur[char] = (compteur[char] || 0) + 1;
        }
        return Object.values(compteur).every((count) => count % 2 === 0);
    }
    console.log(sontAnagrammes("anagram", "margana")); // true
    ```

