function fibonacci(n) {
  if (n <= 1) return n; // Cas de base : f(0)=0 et f(1)=1
  let a = 0, b = 1;
  for (let i = 2; i <= n; i++) {
    const next = a + b;
    a = b;
    b = next;
  }
  return b;
}
```

8. **Algorithmique — Mots uniques** :

```javascript
function motsUniques(s) {
  const ensemble = new Set(); // Ensemble pour stocker les mots uniques (déjà vu ou non)
  for (let mot of s.split(/\s+/)) {
    if (mot !== "") ensemble.add(mot); // Ajouter chaque mot unique à l'ensemble
  }
  return ensemble.size;
}
```

9. **Algorithmique — Aplatir un tableau** :

```javascript
function aplanirTableau(tab) {
  const resultat = [];
  for (let sousTab of tab) {
    if (Array.isArray(sousTab)) {
      resultat.push(...aplatirTableau(sousTab)); // Récursivité pour les tableaux imbriqués
    } else {
      resultat.push(sousTab);
    }
  }
  return resultat;
}
```

10. **Algorithmique — Rotation à droite** :

```javascript
function rotationDroite(tab, k) {
  const n = tab.length;
  k = k % n; // Réduire k modulo la taille du tableau pour éviter les dépassements
  if (k === 0) return [...tab]; // Pas de rotation si k est déjà nul

  // Copie circulaire : on déplace les éléments vers la droite et boucle à partir de l'indice k
  const result = new Array(n);
  for (let i = 0; i < n; i++) {
    result[(i + k) % n] = tab[i]; // Le dernier élément passe en tête, etc.
  }
  return result;
}
```

