function validerParentheses(s) {
  const pile = []; // Pile pour stocker les parenthèses ouvertes
  for (let char of s) {
    if (char === "(") {
      pile.push("("); // Empiler une parenthèse ouverte
    } else if (char === ")") {
      if (pile.length === 0) return false; // Pas de parenthèse ouvrante correspondante
      pile.pop(); // Déempiler la dernière parenthèse ouverte
    }
  }
  return pile.length === 0; // Toutes les parenthèses ont été appariées
}
```

