function rotationDroite(tab, k) {
  const n = tab.length;
  k = k % n; // Réduire k modulo la taille du tableau pour éviter les dépassements
  if (k === 0) return [...tab]; // Pas de rotation si k est déjà nul

  // Copie circulaire : on déplace les éléments vers la droite et boucle à partir de l'indice k
  const result = new Array(n);
  for (let i = 0; i < n; i++) {
    result[(i + k) % n] = tab[i]; // Le dernier élément passe en tête, etc.
