5. **algo_facile_1** — Merge intervals by sorting and merging overlapping pairs (O(n log n))
```javascript
function fusionnerIntervalles(tab) {
  if (!tab.length) return [];
  // Sort by start, then merge overlaps: [a, b] + [b, c] -> [a, c]
  const merged = tab.sort((a, b) => a[0] - b[0]);
  let result = [{ ...merged[0], end: Math.max(merged[0][1], merged[1][1]) }];

  for (let i = 1; i < merged.length; i++) {
    const current = merged[i];
    if (current[0] <= result[result.length - 1][1]) {
      // Overlap: merge ends
      result[result.length - 1].end = Math.max(result[result.length - 1][1], current[1]);
    } else {
      // No overlap: append the next interval
      result.push({ ...current });
    }
  }

  return result;
}

console.log(fusionnerIntervalles([[1, 3], [2, 6]])); // [[1, 6]]
```

