function prefixeCommun(tab) {
  if (!tab.length || !tab[0]) return "";
  let prefix = "";
  for (let i = 0; i < Math.min(...tab.map((s) => s.length)); i++) {
    const char = tab[0][i];
    if (tab.every((s) => s[i] === char)) prefix += char;
    else break;
  }
  return prefix;
}

console.log(prefixeCommun(["apple", "apricot"])); // 'ap'
