    iB = 0;

  // Count how many elements are in the left half of both arrays combined
  let countLeft = Math.floor((total - 1) / 2);
  while (countLeft > 0 && iA < a.length && iB < b.length) {
    if (a[iA] <= b[iB]) {
      countLeft -= Math.min(a[iA], b[iB]); // Count the smaller one
      iA++;
    } else {
      countLeft -= Math.min(b[iB], a[iA]);
      iB++;
    }
  }

  // Now both pointers are at or past their half-way point; find the median:
  if (iA === a.length) return b[iB + countLeft]; // B's left half has more elements
  if (iB === b.length) return a[iA + countLeft]; // A's left half has more elements

  // Both pointers are in the middle: median is their average
  return (Math.min(a[iA], b[iB]) + Math.max(a[iA], b[iB])) / 2;
}

console.log(medianDeuxTries([1, 3, 5], [2, 4])); // 3
```

9. **algo_defi** — Longest increasing subsequence (O(n log n))
```javascript
function plusLongueSousSuiteCroissante(tab) {
  const dp = new Array(tab.length).fill(1);
  let maxLen = 1;

  for (let i = 0; i < tab.length; i++) {
    for (let j = 0; j < i; j++) {
      if (tab[j] < tab[i]) dp[i] = Math.max(dp[i], dp[j] + 1);
    }
    maxLen = Math.max(maxLen, dp[i]);
  }

  return maxLen;
}

console.log(plusLongueSousSuiteCroissante([10, 9, 2, 5, 3, 7, 101, 18])); // 4 (e.g., [2, 3, 7, 101])
